insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-plain-session-short-and-queue-keeps-running-sam-2026-11-22','decision','A plain session stays short and never stands the queue down','Sam, 2026-11-22, in session (S702): "something went off the rails in my last session which ran about 8 hours, which is about 7 hours longer than expected and it derailed cpl queue from the nightly run, so lost a whole night. Just don''t want that to happen again with this session." A plain session runs about an hour and coordinates with the queue without stopping it.',array['sessions','queue','scheduled-sessions'],'verified','Sam in session, 2026-11-22 (S702)','Sam',now(),'SkyRazorbill (S702)','2026-11-22'),
('p-plain-session-pr-needs-declared-scope-s702','pitfall','A plain session''s PR with no declared scope stands every queue firing down','On 2026-11-22 the 10:12Z CPL Queue firing ended in two minutes because S701''s open PR named no side-session scope; the same happened through the night. A session Sam opens inside the routine''s hours (06:12Z to 14:12Z) opens a draft PR in its first minutes whose body declares its scope in the shape scheduled_sessions.md step 1 gives, and says the routine proceeds. S702 did so with #3673.',array['sessions','queue','scheduled-sessions'],'proposed','docs/session_703_handoff.md; docs/reference/scheduled_sessions.md step 1; PR #3673',null,null,'SkyRazorbill (S702)','2026-11-22'),
('d-subjects-panel-address-over-a-surface-s702','decision','The Subjects course panel opens over any surface, addressed all/<college>/<code>','S702 (#3673): the course panel and Edit open from every Subjects surface and Close returns to it. Over the front list the address is #commons/subjects/all/<college>/<code>; over the no-title, held and noncredit lists it is #commons/subjects/<list>/<college>/<code>; a college''s own view keeps <college>/<code>. Sky''s call, Sam''s to revise.',array['commons','subjects'],'proposed','PR #3673; tests/commons_subjects_every_surface.test.js',null,null,'SkyRazorbill (S702)','2026-11-22'),
('d-subjects-several-colleges-one-press-each-s702','decision','A code wrong at several colleges is settled one college at a time for now','S702 (#3673): the Subjects panel lists the other colleges on file that use the same local code, and each opens its own form. One Save that settles the code at every college is the next slice: a noncredit code''s save key differs by COCI category at each college, so the action must build each college''s key. Sky''s call, Sam''s to revise.',array['commons','subjects'],'proposed','PR #3673; docs/reference/lanes/commons.md',null,null,'SkyRazorbill (S702)','2026-11-22')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyRazorbill (S702)', 'create', 'S702 (2026-11-22)', to_jsonb(m)
from public.cpl_memory m where m.author = 'SkyRazorbill (S702)'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select slug, status, length(summary) from public.cpl_memory where author = 'SkyRazorbill (S702)' order by slug;
